frappe.ui.form.on("Project Estimation", {
    customer(frm) {
        if (!frm.doc.customer) {
            frm.set_value("country", "");
            return;
        }

        frappe.call({
            method: "frappe.contacts.doctype.address.address.get_default_address",
            args: {
                doctype: "Customer",
                name: frm.doc.customer
            },
            callback: function(r) {
                if (r.message) {
                    frappe.db.get_value(
                        "Address",
                        r.message,
                        "country",
                        function(res) {
                            if (res) {
                                frm.set_value("country", res.country);
                            }
                        }
                    );
                } else {
                    frm.set_value("country", "");
                }
            }
        });
    }
});

frappe.ui.form.on("BOQMATERIAL", {
    part_no(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (!row.part_no) return;

        frappe.db.get_doc("Item", row.part_no).then(item => {

            frappe.model.set_value(cdt, cdn, "description",
                item.description || item.item_name
            );

            frappe.model.set_value(cdt, cdn, "unit", item.stock_uom);

        });
    }
});

frappe.ui.form.on("Project Estimation", {

    costing_method(frm) {
        recalculate_all_rows(frm);
    }

});


frappe.ui.form.on("BOQMATERIAL", {

    part_no(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row.part_no) return;

        frappe.db.get_doc("Item", row.part_no).then(item => {
            frappe.model.set_value(
                cdt,
                cdn,
                "description",
                item.description || item.item_name
            );
            frappe.model.set_value(
                cdt,
                cdn,
                "unit",
                item.stock_uom
            );
            fetch_item_cost(frm, cdt, cdn);

        });

    },

    quantity(frm, cdt, cdn) {
        calculate_amount(cdt, cdn);
    },

    unit_cost(frm, cdt, cdn) {
        calculate_amount(cdt, cdn);
    },

    unit_costlc(frm, cdt, cdn) {
        calculate_amount(cdt, cdn);
    }

});



function recalculate_all_rows(frm) {

    (frm.doc.material_charges || []).forEach(function(row) {

        fetch_item_cost(frm, row.doctype, row.name);

    });

}



function fetch_item_cost(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    if (!row.part_no)
        return;

    switch (frm.doc.costing_method) {

        case "Standard Rate":

            frappe.db.get_value(
                "Item",
                row.part_no,
                "standard_rate"
            ).then(r => {

                let rate = flt(r.message.standard_rate);

                frappe.model.set_value(cdt, cdn, "unit_cost", rate);
                frappe.model.set_value(cdt, cdn, "unit_costlc", rate);

                calculate_amount(cdt, cdn);

            });

            break;


        case "Manual":
            calculate_amount(cdt, cdn);

            break;


  case "Last Purchase Rate":

    frappe.db.get_list("Purchase Receipt Item", {
    filters: {
        item_code: row.part_no,
        docstatus: 1
    },
    fields: [
        "parent",
        "rate",
        "base_rate",
        "amount",
        "base_amount"
    ],
    order_by: "creation desc",
    limit: 1
}).then(r => {
   console.log(r);
});

    break;


        case "Valuation Rate":

    frappe.db.get_list("Bin", {
        filters: {
            item_code: row.part_no,
            company: frm.doc.company
        },
        fields: ["valuation_rate"],
        limit: 1
    }).then(r => {

        let rate = (r.length > 0) ? flt(r[0].valuation_rate) : 0;

        frappe.model.set_value(cdt, cdn, "unit_cost", rate);
        frappe.model.set_value(cdt, cdn, "unit_costlc", rate);

        calculate_amount(cdt, cdn);

    });

    break;


        case "Price List":

    frappe.db.get_list("Item Price", {
        filters: {
            item_code: row.part_no,
            price_list: frm.doc.buying_price_list
        },
        fields: ["price_list_rate"],
        limit: 1
    }).then(r => {

        let rate = (r.length > 0) ? flt(r[0].price_list_rate) : 0;

        frappe.model.set_value(cdt, cdn, "unit_cost", rate);
        frappe.model.set_value(cdt, cdn, "unit_costlc", rate);

        calculate_amount(cdt, cdn);

    });

    break;

    }

}



function calculate_amount(cdt, cdn) {

    let row = locals[cdt][cdn];

    let qty = flt(row.quantity);
    let rate = flt(row.unit_costlc);

    frappe.model.set_value(
        cdt,
        cdn,
        "amountlc",
        qty * rate
    );

}

frappe.ui.form.on("Project Estimation", {
    setup(frm) {
        frm.set_query("description", "freight_charges", function() {
            return {
                filters: {
                    item_group: "Services",
                    disabled: 0
                }
            };
        });
    }
});

function calculate_totals(frm) {

    // Material Total
    let material_total = 0;
    (frm.doc.boqmaterialcharges || []).forEach(row => {
        material_total += flt(row.amountlc);
    });
    frm.set_value("total_items", material_total);

    // Freight Total
    let freight_total = 0;
    (frm.doc.freight_charges || []).forEach(row => {
        freight_total += flt(row.amountlc);
    });
    frm.set_value("total_freight", freight_total);
    frm.set_value("5", freight_total + material_total );
    //frm.set_value("4", freight_total + material_total );
    // Local Charges Total
    let local_total = 0;
    (frm.doc.local_charges || []).forEach(row => {
        local_total += flt(row.amountlc);
    });
    frm.set_value("total_local_charges", local_total);
    frm.set_value("6", local_total);
    // Site Charges Total
    let site_total = 0;
    (frm.doc.site_charges || []).forEach(row => {
        site_total += flt(row.amountlc);
    });
    frm.set_value("total_site_charges", site_total);
    frm.set_value("7", site_total);
    // Manpower Total
    let manpower_total = 0;
    (frm.doc.manpower_charges || []).forEach(row => {
        manpower_total += flt(row.amountlc);
    });
    frm.set_value("total_manpower", manpower_total);

    // Refresh calculated fields
    frm.refresh_fields([
        "total_items",
        "total_freight",
        "total_local_charges",
        "6",
        "7",
        "8",
        "4",
        "14",
        "float_asas",
        "total_site_charges",
        "total_manpower"
    ]);
    frm.set_value("8",site_total +local_total+ freight_total+ material_total );
    let total_expense =
        material_total +
        freight_total +
        local_total +
        site_total;
        
     let percent = flt(frm.doc.profit_percent);

    let profit = total_expense * percent / 100;
    frm.set_value("14", profit);
    
    let income = total_expense+profit;
    frm.set_value("float_asas", income);
    frm.set_value("4", income);
}


// Parent
frappe.ui.form.on("Project Estimation", {
    refresh(frm) {
        calculate_totals(frm);
    },
     profit_percent(frm) {
        calculate_totals(frm);
    }
})
 

// Material Charges
frappe.ui.form.on("BOQMATERIAL", {

    amountlc(frm) {
        calculate_totals(frm);
    },

    boqmaterialcharges_add(frm) {
        calculate_totals(frm);
    },

    boqmaterialcharges_remove(frm) {
        calculate_totals(frm);
    }

});


// Freight Charges
frappe.ui.form.on("BOQFRCHARG", {

    amountlc(frm) {
        calculate_totals(frm);
    },

    freight_charges_add(frm) {
        calculate_totals(frm);
    },

    freight_charges_remove(frm) {
        calculate_totals(frm);
    }

});


// Local Charges
frappe.ui.form.on("BOQLOCALCHARG", {

    amountlc(frm) {
        calculate_totals(frm);
    },

    local_charges_add(frm) {
        calculate_totals(frm);
    },

    local_charges_remove(frm) {
