});


// Site Charges
frappe.ui.form.on("BOQSITECHARG", {

    amountlc(frm) {
        calculate_totals(frm);
    },

    site_charges_add(frm) {
        calculate_totals(frm);
    },

    site_charges_remove(frm) {
        calculate_totals(frm);
    }

});


// Manpower Charges
frappe.ui.form.on("BOQMANPCHARGES", {

    amountlc(frm) {
        calculate_totals(frm);
    },

    manpower_charges_add(frm) {
        calculate_totals(frm);
    },

    manpower_charges_remove(frm) {
